import { createClient } from '@supabase/supabase-js'

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL
const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY

if (!supabaseUrl || !supabaseAnonKey) {
  throw new Error('Missing Supabase environment variables. Check your .env file.')
}

export const supabase = createClient(supabaseUrl, supabaseAnonKey)

/**
 * Grade color mapping for security scores.
 * A = green, B = blue, C = amber, D = orange, F = red
 */
export const GRADE_COLORS = {
  A: { bg: '#059669', text: '#ffffff', light: '#d1fae5', border: '#059669' },
  B: { bg: '#2563eb', text: '#ffffff', light: '#dbeafe', border: '#2563eb' },
  C: { bg: '#d97706', text: '#ffffff', light: '#fef3c7', border: '#d97706' },
  D: { bg: '#ea580c', text: '#ffffff', light: '#ffedd5', border: '#ea580c' },
  F: { bg: '#dc2626', text: '#ffffff', light: '#fee2e2', border: '#dc2626' },
}

export const CRITICALITY_COLORS = {
  critical: { bg: 'bg-red-100', text: 'text-red-800', border: 'border-red-200' },
  high: { bg: 'bg-orange-100', text: 'text-orange-800', border: 'border-orange-200' },
  medium: { bg: 'bg-amber-100', text: 'text-amber-800', border: 'border-amber-200' },
  low: { bg: 'bg-gray-100', text: 'text-gray-600', border: 'border-gray-200' },
}

export const SEVERITY_COLORS = {
  HIGH: { bg: 'bg-red-50', text: 'text-red-700', badge: 'bg-red-100 text-red-800', border: 'border-red-200' },
  MEDIUM: { bg: 'bg-amber-50', text: 'text-amber-700', badge: 'bg-amber-100 text-amber-800', border: 'border-amber-200' },
  LOW: { bg: 'bg-blue-50', text: 'text-blue-700', badge: 'bg-blue-100 text-blue-800', border: 'border-blue-200' },
  INFO: { bg: 'bg-gray-50', text: 'text-gray-600', badge: 'bg-gray-100 text-gray-700', border: 'border-gray-200' },
}

export function getGradeStyle(grade) {
  return GRADE_COLORS[grade] || GRADE_COLORS['F']
}

export function getCriticalityStyle(criticality) {
  return CRITICALITY_COLORS[criticality?.toLowerCase()] || CRITICALITY_COLORS.low
}

export function getSeverityStyle(severity) {
  return SEVERITY_COLORS[severity?.toUpperCase()] || SEVERITY_COLORS.INFO
}

export function scoreToGrade(score) {
  if (score >= 90) return 'A'
  if (score >= 80) return 'B'
  if (score >= 70) return 'C'
  if (score >= 60) return 'D'
  return 'F'
}

export function formatDelta(delta) {
  if (delta === null || delta === undefined) return null
  const num = parseFloat(delta)
  if (isNaN(num)) return null
  return num
}

export function formatScore(score) {
  if (score === null || score === undefined) return '--'
  return Math.round(score)
}

export function formatDate(dateStr) {
  if (!dateStr) return 'Never'
  const d = new Date(dateStr)
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
}

export function formatDateShort(dateStr) {
  if (!dateStr) return '--'
  const d = new Date(dateStr)
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
}

import { useState, useEffect, useCallback } from 'react'
import { useParams, Link, useNavigate } from 'react-router-dom'
import {
  Shield,
  ArrowUpDown,
  Globe,
  AlertTriangle,
  CheckCircle2,
  BarChart2,
} from 'lucide-react'
import { supabase } from '../lib/supabase'
import { formatScore, formatDate, getGradeStyle, scoreToGrade } from '../lib/gradeUtils'
import AppHeader from '../components/AppHeader'
import GradeBadge from '../components/GradeBadge'
import CriticalityBadge from '../components/CriticalityBadge'
import DeltaIndicator from '../components/DeltaIndicator'
import LoadingSpinner from '../components/LoadingSpinner'
import ErrorMessage from '../components/ErrorMessage'

/**
 * Per-client dashboard showing:
 * - Posture summary header with KPIs
 * - Vendor scorecard table sorted worst-first by default
 */
export default function ClientDashboard() {
  const { clientSlug } = useParams()
  const navigate = useNavigate()

  const [client, setClient] = useState(null)
  const [vendors, setVendors] = useState([])
  const [alertCount, setAlertCount] = useState(0)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  // Table sort state — default: score ascending (worst first)
  const [sortField, setSortField] = useState('last_score')
  const [sortDir, setSortDir] = useState('asc')

  const loadData = useCallback(async () => {
    setLoading(true)
    setError(null)

    try {
      // Load client by slug
      const { data: clientData, error: clientErr } = await supabase
        .from('sentinel_clients')
        .select('*')
        .eq('slug', clientSlug)
        .single()

      if (clientErr) throw clientErr
      setClient(clientData)

      // Load vendors for this client
      const { data: vendorData, error: vendorErr } = await supabase
        .from('sentinel_vendors')
        .select('*')
        .eq('client_id', clientData.id)

      if (vendorErr) throw vendorErr
      setVendors(vendorData || [])

      // Unacknowledged alert count
      const { count } = await supabase
        .from('sentinel_alerts')
        .select('id', { count: 'exact', head: true })
        .eq('client_id', clientData.id)
        .is('acknowledged', null)

      setAlertCount(count || 0)
    } catch (err) {
      console.error('Failed to load client dashboard:', err)
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }, [clientSlug])

  useEffect(() => {
    loadData()
  }, [loadData])

  // Derived stats for the posture summary
  const scoredVendors = vendors.filter((v) => v.last_score !== null)
  const avgScore =
    scoredVendors.length > 0
      ? scoredVendors.reduce((sum, v) => sum + v.last_score, 0) / scoredVendors.length
      : null
  const overallGrade = avgScore !== null ? scoreToGrade(avgScore) : null
  const overallGradeStyle = overallGrade ? getGradeStyle(overallGrade) : null

  const criticalVendors = vendors.filter(
    (v) => v.criticality === 'critical' && v.last_score !== null && v.last_score < 70
  )
  const monitoredCount = vendors.filter((v) => v.monitoring_enabled).length

  // Sorted vendors
  const sortedVendors = [...vendors].sort((a, b) => {
    let aVal = a[sortField]
    let bVal = b[sortField]

    // Push nulls to end
    if (aVal === null || aVal === undefined) return 1
    if (bVal === null || bVal === undefined) return -1

    if (typeof aVal === 'string') aVal = aVal.toLowerCase()
    if (typeof bVal === 'string') bVal = bVal.toLowerCase()

    const cmp = aVal < bVal ? -1 : aVal > bVal ? 1 : 0
    return sortDir === 'asc' ? cmp : -cmp
  })

  function handleSort(field) {
    if (sortField === field) {
      setSortDir((d) => (d === 'asc' ? 'desc' : 'asc'))
    } else {
      setSortField(field)
      setSortDir('asc')
    }
  }

  function SortIcon({ field }) {
    if (sortField !== field) return <ArrowUpDown className="w-3.5 h-3.5 text-slate-400" />
    return (
      <span className="text-mtm-teal font-bold text-xs">
        {sortDir === 'asc' ? '↑' : '↓'}
      </span>
    )
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-mtm-bg">
        <AppHeader />
        <LoadingSpinner message="Loading client dashboard..." />
      </div>
    )
  }

  if (error) {
    return (
      <div className="min-h-screen bg-mtm-bg">
        <AppHeader />
        <ErrorMessage message={error} onRetry={loadData} />
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-mtm-bg">
      <AppHeader
        clientName={client?.name}
        clientSlug={clientSlug}
        alertCount={alertCount}
      />

      <main className="max-w-screen-xl mx-auto px-4 sm:px-6 py-6 sm:py-8">
        {/* Posture summary header */}
        <div
          className="rounded-xl p-6 mb-8 text-white shadow-md"
          style={{ background: 'linear-gradient(135deg, #0f172a 0%, #1e3a5f 100%)' }}
        >
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-6">
            <div className="flex items-center gap-5">
              {overallGradeStyle ? (
                <div
                  className="w-20 h-20 rounded-2xl flex items-center justify-center text-5xl font-extrabold shadow-lg flex-shrink-0"
                  style={{ backgroundColor: overallGradeStyle.bg, color: overallGradeStyle.text }}
                >
                  {overallGrade}
                </div>
              ) : (
                <div className="w-20 h-20 rounded-2xl flex items-center justify-center bg-slate-700 flex-shrink-0">
                  <Shield className="w-10 h-10 text-slate-400" />
                </div>
              )}
              <div>
                <h1 className="text-2xl font-bold text-white">{client?.name}</h1>
                <p className="text-slate-300 mt-1">
                  {avgScore !== null
                    ? `Overall security posture score: ${formatScore(avgScore)}/100`
                    : 'No scores available yet'}
                </p>
              </div>
            </div>

            {/* KPI row */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 md:gap-4">
              <div className="bg-white/10 rounded-lg p-3 md:p-4 text-center">
                <p className="text-xl md:text-2xl font-bold text-white">{vendors.length}</p>
                <p className="text-xs text-slate-300 mt-0.5">Total Vendors</p>
              </div>
              <div className="bg-white/10 rounded-lg p-3 md:p-4 text-center">
                <p className="text-xl md:text-2xl font-bold text-white">{monitoredCount}</p>
                <p className="text-xs text-slate-300 mt-0.5">Monitored</p>
              </div>
              <div
                className={`rounded-lg p-3 md:p-4 text-center ${
                  criticalVendors.length > 0 ? 'bg-red-900/40' : 'bg-white/10'
                }`}
              >
                <p
                  className={`text-xl md:text-2xl font-bold ${
                    criticalVendors.length > 0 ? 'text-red-300' : 'text-white'
                  }`}
                >
                  {criticalVendors.length}
                </p>
                <p className="text-xs text-slate-300 mt-0.5">Critical Risk</p>
              </div>
              <div
                className={`rounded-lg p-3 md:p-4 text-center ${
                  alertCount > 0 ? 'bg-amber-900/40' : 'bg-white/10'
                }`}
              >
                <p
                  className={`text-xl md:text-2xl font-bold ${alertCount > 0 ? 'text-amber-300' : 'text-white'}`}
                >
                  {alertCount}
                </p>
                <p className="text-xs text-slate-300 mt-0.5">Open Alerts</p>
              </div>
            </div>
          </div>
        </div>

        {/* Vendor scorecard table */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between">
            <div>
              <h2 className="text-base font-bold text-slate-900">Vendor Scorecard</h2>
              <p className="text-xs text-slate-500 mt-0.5">
                {vendors.length} vendor{vendors.length !== 1 ? 's' : ''} — sorted worst first by default
              </p>
            </div>
            <div className="hidden sm:flex items-center gap-2 text-xs text-slate-400">
              <BarChart2 className="w-4 h-4" />
              <span>Click a row to view details</span>
            </div>
          </div>

          {vendors.length === 0 ? (
            <div className="text-center py-16">
              <Globe className="w-10 h-10 text-slate-300 mx-auto mb-3" />
              <p className="text-slate-500">No vendors found for this client.</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-slate-50 text-slate-600 text-xs uppercase tracking-wider">
                    <th className="text-left px-6 py-3 font-semibold">
                      <button
                        onClick={() => handleSort('name')}
                        className="flex items-center gap-1.5 hover:text-slate-900 transition-colors"
                      >
                        Vendor <SortIcon field="name" />
                      </button>
                    </th>
                    <th className="text-left px-4 py-3 font-semibold">
                      <button
                        onClick={() => handleSort('domain')}
                        className="flex items-center gap-1.5 hover:text-slate-900 transition-colors"
                      >
                        Domain <SortIcon field="domain" />
                      </button>
                    </th>
                    <th className="text-center px-4 py-3 font-semibold">
                      <button
                        onClick={() => handleSort('last_grade')}
                        className="flex items-center gap-1.5 hover:text-slate-900 transition-colors mx-auto"
                      >
                        Grade <SortIcon field="last_grade" />
                      </button>
                    </th>
                    <th className="text-center px-4 py-3 font-semibold">
                      <button
                        onClick={() => handleSort('last_score')}
                        className="flex items-center gap-1.5 hover:text-slate-900 transition-colors mx-auto"
                      >
                        Score <SortIcon field="last_score" />
                      </button>
                    </th>
                    <th className="text-center px-4 py-3 font-semibold">
                      <button
                        onClick={() => handleSort('criticality')}
                        className="flex items-center gap-1.5 hover:text-slate-900 transition-colors mx-auto"
                      >
                        Criticality <SortIcon field="criticality" />
                      </button>
                    </th>
                    <th className="text-center px-4 py-3 font-semibold">
                      <button
                        onClick={() => handleSort('last_scanned_at')}
                        className="flex items-center gap-1.5 hover:text-slate-900 transition-colors mx-auto"
                      >
                        Last Scanned <SortIcon field="last_scanned_at" />
                      </button>
                    </th>
                    <th className="text-center px-4 py-3 font-semibold">Change</th>
                    <th className="text-center px-4 py-3 font-semibold">
                      <button
                        onClick={() => handleSort('auto_recommendation')}
                        className="flex items-center gap-1.5 hover:text-slate-900 transition-colors mx-auto"
                      >
                        Recommendation <SortIcon field="auto_recommendation" />
                      </button>
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {sortedVendors.map((vendor) => {
                    const gradeStyle = vendor.last_grade
                      ? getGradeStyle(vendor.last_grade)
                      : null

                    return (
                      <tr
                        key={vendor.id}
                        onClick={() => navigate(`/client/${clientSlug}/vendor/${vendor.id}`)}
                        className="hover:bg-slate-50 transition-colors cursor-pointer"
                      >
                        <td className="px-6 py-4">
                          <div>
                            <p className="font-semibold text-slate-900">{vendor.name}</p>
                            {vendor.category && (
                              <p className="text-xs text-slate-400 mt-0.5">{vendor.category}</p>
                            )}
                          </div>
                        </td>
                        <td className="px-4 py-4">
                          <span className="text-slate-600 font-mono text-xs">{vendor.domain || '--'}</span>
                        </td>
                        <td className="px-4 py-4 text-center">
                          {vendor.last_grade ? (
                            <div
                              className="w-9 h-9 rounded-lg flex items-center justify-center text-base font-extrabold mx-auto"
                              style={{
                                backgroundColor: gradeStyle?.bg,
                                color: gradeStyle?.text,
                              }}
                            >
                              {vendor.last_grade}
                            </div>
                          ) : (
                            <span className="text-slate-400">--</span>
                          )}
                        </td>
                        <td className="px-4 py-4 text-center">
                          <span
                            className="text-base font-bold"
                            style={gradeStyle ? { color: gradeStyle.bg } : { color: '#94a3b8' }}
                          >
                            {formatScore(vendor.last_score)}
                          </span>
                        </td>
                        <td className="px-4 py-4 text-center">
                          <CriticalityBadge criticality={vendor.criticality} />
                        </td>
                        <td className="px-4 py-4 text-center text-xs text-slate-500">
                          {formatDate(vendor.last_scanned_at)}
                        </td>
                        <td className="px-4 py-4 text-center">
                          <DeltaIndicator delta={vendor.score_delta ?? vendor.last_score_delta} />
                        </td>
                        <td className="px-4 py-4 text-center">
                          {vendor.auto_recommendation === 'approved' ? (
                            <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-semibold bg-emerald-50 text-emerald-700 border border-emerald-200">
                              <CheckCircle2 className="w-3 h-3" />
                              Approved
                            </span>
                          ) : vendor.auto_recommendation === 'conditional' ? (
                            <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-semibold bg-amber-50 text-amber-700 border border-amber-200">
                              <AlertTriangle className="w-3 h-3" />
                              Conditional
                            </span>
                          ) : vendor.auto_recommendation === 'not_approved' ? (
                            <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-semibold bg-red-50 text-red-700 border border-red-200">
                              <AlertTriangle className="w-3 h-3" />
                              Not Approved
                            </span>
                          ) : (
                            <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-semibold bg-slate-50 text-slate-500 border border-slate-200">
                              Needs Review
                            </span>
                          )}
                          {vendor.manual_override && (
                            <span className="block text-[10px] text-slate-400 mt-0.5">
                              Overridden
                            </span>
                          )}
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </main>
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { useParams, Link } from 'react-router-dom'
import {
  ArrowLeft,
  Globe,
  ChevronDown,
  ChevronUp,
  AlertTriangle,
  Info,
} from 'lucide-react'
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  Cell,
  LineChart,
  Line,
  CartesianGrid,
  ReferenceLine,
} from 'recharts'
import { supabase } from '../lib/supabase'
import {
  formatScore,
  formatDate,
  getGradeStyle,
  scoreToGrade,
  getSeverityStyle,
} from '../lib/gradeUtils'
import AppHeader from '../components/AppHeader'
import GradeBadge from '../components/GradeBadge'
import CriticalityBadge from '../components/CriticalityBadge'
import DeltaIndicator from '../components/DeltaIndicator'
import LoadingSpinner from '../components/LoadingSpinner'
import ErrorMessage from '../components/ErrorMessage'

/**
 * Vendor detail page.
 * Shows: header summary, 9-factor bar chart, findings grouped by severity, assessment history timeline.
 */
export default function VendorDetail() {
  const { clientSlug, vendorId } = useParams()

  const [client, setClient] = useState(null)
  const [vendor, setVendor] = useState(null)
  const [assessments, setAssessments] = useState([])
  const [alertCount, setAlertCount] = useState(0)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  // Track which severity sections are collapsed
  const [collapsed, setCollapsed] = useState({})

  const loadData = useCallback(async () => {
    setLoading(true)
    setError(null)

    try {
      // Load client
      const { data: clientData, error: clientErr } = await supabase
        .from('sentinel_clients')
        .select('*')
        .eq('slug', clientSlug)
        .single()
      if (clientErr) throw clientErr
      setClient(clientData)

      // Load vendor
      const { data: vendorData, error: vendorErr } = await supabase
        .from('sentinel_vendors')
        .select('*')
        .eq('id', vendorId)
        .single()
      if (vendorErr) throw vendorErr
      setVendor(vendorData)

      // Load assessments (most recent first)
      const { data: assessmentData, error: assessErr } = await supabase
        .from('sentinel_assessments')
        .select('*')
        .eq('vendor_id', vendorId)
        .order('assessed_at', { ascending: false })
      if (assessErr) throw assessErr
      setAssessments(assessmentData || [])

      // Alert count
      const { count } = await supabase
        .from('sentinel_alerts')
        .select('id', { count: 'exact', head: true })
        .eq('client_id', clientData.id)
        .is('acknowledged', null)
      setAlertCount(count || 0)
    } catch (err) {
      console.error('Failed to load vendor detail:', err)
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }, [clientSlug, vendorId])

  useEffect(() => {
    loadData()
  }, [loadData])

  if (loading) {
    return (
      <div className="min-h-screen bg-mtm-bg">
        <AppHeader clientName={client?.name} clientSlug={clientSlug} />
        <LoadingSpinner message="Loading vendor details..." />
      </div>
    )
  }

  if (error) {
    return (
      <div className="min-h-screen bg-mtm-bg">
        <AppHeader clientName={client?.name} clientSlug={clientSlug} />
        <ErrorMessage message={error} onRetry={loadData} />
      </div>
    )
  }

  // Latest assessment for factor scores and findings
  const latestAssessment = assessments[0] || null
  const factorScores = latestAssessment?.factor_scores || {}
  const findings = latestAssessment?.findings || []
  const findingCounts = latestAssessment?.finding_counts || {}

  // Build factor bar chart data
  const factorData = Object.entries(factorScores)
    .map(([name, score]) => ({
      name: formatFactorName(name),
      rawName: name,
      score: Math.round(score),
      grade: scoreToGrade(score),
    }))
    .sort((a, b) => a.score - b.score) // worst first

  // Group findings by severity
  const severityOrder = ['HIGH', 'MEDIUM', 'LOW', 'INFO']
  const groupedFindings = {}
  severityOrder.forEach((sev) => {
    const items = Array.isArray(findings)
      ? findings.filter((f) => (f.severity || '').toUpperCase() === sev)
      : []
    if (items.length > 0) groupedFindings[sev] = items
  })

  // History timeline data (oldest first for chart)
  const historyData = [...assessments]
    .reverse()
    .map((a) => ({
      date: formatDate(a.assessed_at),
      score: Math.round(a.overall_score),
      grade: a.overall_grade,
    }))

  const gradeStyle = vendor?.last_grade ? getGradeStyle(vendor.last_grade) : null

  function toggleSection(sev) {
    setCollapsed((prev) => ({ ...prev, [sev]: !prev[sev] }))
  }

  return (
    <div className="min-h-screen bg-mtm-bg">
      <AppHeader
        clientName={client?.name}
        clientSlug={clientSlug}
        vendorName={vendor?.name}
        alertCount={alertCount}
      />

      <main className="max-w-screen-xl mx-auto px-4 sm:px-6 py-6 sm:py-8 space-y-6">
        {/* Back link */}
        <Link
          to={`/client/${clientSlug}`}
          className="inline-flex items-center gap-1.5 text-sm text-slate-500 hover:text-slate-900 transition-colors"
        >
          <ArrowLeft className="w-4 h-4" />
          Back to {client?.name}
        </Link>

        {/* Vendor header card */}
        <div
          className="rounded-xl p-6 text-white shadow-md"
          style={{ background: 'linear-gradient(135deg, #0f172a 0%, #1e3a5f 100%)' }}
        >
          <div className="flex flex-col md:flex-row md:items-start gap-5">
            {/* Grade */}
            {gradeStyle ? (
              <div
                className="w-20 h-20 rounded-2xl flex items-center justify-center text-5xl font-extrabold shadow-lg flex-shrink-0"
                style={{ backgroundColor: gradeStyle.bg, color: gradeStyle.text }}
              >
                {vendor.last_grade}
              </div>
            ) : (
