        {/* Assessment history table */}
        {assessments.length > 0 && (
          <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="px-6 py-4 border-b border-slate-100">
              <h2 className="text-base font-bold text-slate-900">Assessment History</h2>
              <p className="text-xs text-slate-500 mt-0.5">{assessments.length} total assessments</p>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-slate-50 text-slate-500 text-xs uppercase tracking-wider">
                    <th className="text-left px-6 py-3 font-semibold">Date</th>
                    <th className="text-center px-4 py-3 font-semibold">Grade</th>
                    <th className="text-center px-4 py-3 font-semibold">Score</th>
                    <th className="text-center px-4 py-3 font-semibold">Change</th>
                    <th className="text-center px-4 py-3 font-semibold">High</th>
                    <th className="text-center px-4 py-3 font-semibold">Medium</th>
                    <th className="text-center px-4 py-3 font-semibold">Low</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {assessments.map((a) => {
                    const gs = a.overall_grade ? getGradeStyle(a.overall_grade) : null
                    const fc = a.finding_counts || {}
                    return (
                      <tr key={a.id} className="hover:bg-slate-50 transition-colors">
