}

/**
 * Convert snake_case factor key to a readable label.
 * e.g. "network_security" -> "Network Security"
 */
function formatFactorName(key) {
  return key
    .replace(/_/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase())
    .replace(/\bTls\b/g, 'TLS')
    .replace(/\bDns\b/g, 'DNS')
    .replace(/\bSsl\b/g, 'SSL')
    .replace(/\bSpf\b/g, 'SPF')
    .replace(/\bDkim\b/g, 'DKIM')
    .replace(/\bDmarc\b/g, 'DMARC')
}

import { useState, useEffect, useCallback } from 'react'
import { useParams, Link } from 'react-router-dom'
import {
  Bell,
  CheckCircle2,
  AlertTriangle,
  Info,
  ArrowLeft,
  RefreshCw,
} from 'lucide-react'
import { supabase } from '../lib/supabase'
import { formatDate, getSeverityStyle } from '../lib/gradeUtils'
import AppHeader from '../components/AppHeader'
import LoadingSpinner from '../components/LoadingSpinner'
import ErrorMessage from '../components/ErrorMessage'

/**
 * Alerts feed for a client — shows all alerts sorted by recency.
 * Allows acknowledging individual alerts.
 */
export default function AlertsFeed() {
  const { clientSlug } = useParams()

  const [client, setClient] = useState(null)
  const [alerts, setAlerts] = useState([])
  const [vendorMap, setVendorMap] = useState({})
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [acknowledging, setAcknowledging] = useState(new Set())

  // Filter state
  const [showAcknowledged, setShowAcknowledged] = useState(false)
  const [filterSeverity, setFilterSeverity] = useState('ALL')

  const loadData = useCallback(async () => {
    setLoading(true)
    setError(null)

    try {
      const { data: clientData, error: clientErr } = await supabase
        .from('sentinel_clients')
        .select('*')
        .eq('slug', clientSlug)
        .single()
      if (clientErr) throw clientErr
      setClient(clientData)

      // Load alerts for this client
      const { data: alertData, error: alertErr } = await supabase
        .from('sentinel_alerts')
        .select('*')
        .eq('client_id', clientData.id)
        .order('sent_at', { ascending: false })
      if (alertErr) throw alertErr
      setAlerts(alertData || [])

      // Load vendors for name lookup
      const { data: vendorData } = await supabase
        .from('sentinel_vendors')
        .select('id, name, domain')
        .eq('client_id', clientData.id)

      const map = {}
      ;(vendorData || []).forEach((v) => {
        map[v.id] = v
      })
      setVendorMap(map)
    } catch (err) {
      console.error('Failed to load alerts:', err)
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }, [clientSlug])

  useEffect(() => {
    loadData()
  }, [loadData])

  async function acknowledgeAlert(alertId) {
    setAcknowledging((prev) => new Set([...prev, alertId]))
    try {
      const { error } = await supabase
        .from('sentinel_alerts')
        .update({ acknowledged: new Date().toISOString() })
        .eq('id', alertId)

      if (error) throw error

      setAlerts((prev) =>
        prev.map((a) =>
          a.id === alertId ? { ...a, acknowledged: new Date().toISOString() } : a
        )
      )
    } catch (err) {
      console.error('Failed to acknowledge alert:', err)
    } finally {
      setAcknowledging((prev) => {
        const next = new Set(prev)
        next.delete(alertId)
        return next
      })
    }
  }

  const unacknowledgedCount = alerts.filter((a) => !a.acknowledged).length

  const filteredAlerts = alerts.filter((a) => {
    if (!showAcknowledged && a.acknowledged) return false
    if (filterSeverity !== 'ALL' && (a.severity || '').toUpperCase() !== filterSeverity) return false
    return true
  })

  const SEVERITY_ICON = {
    HIGH: <AlertTriangle className="w-4 h-4 text-red-500 flex-shrink-0" />,
    MEDIUM: <AlertTriangle className="w-4 h-4 text-amber-500 flex-shrink-0" />,
    LOW: <Info className="w-4 h-4 text-blue-500 flex-shrink-0" />,
    INFO: <Info className="w-4 h-4 text-slate-400 flex-shrink-0" />,
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-mtm-bg">
        <AppHeader clientName={client?.name} clientSlug={clientSlug} />
        <LoadingSpinner message="Loading alerts..." />
      </div>
    )
  }

  if (error) {
    return (
      <div className="min-h-screen bg-mtm-bg">
        <AppHeader clientName={client?.name} clientSlug={clientSlug} />
        <ErrorMessage message={error} onRetry={loadData} />
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-mtm-bg">
      <AppHeader
        clientName={client?.name}
        clientSlug={clientSlug}
        alertCount={unacknowledgedCount}
      />

      <main className="max-w-screen-xl mx-auto px-4 sm:px-6 py-6 sm:py-8">
        {/* Back link */}
        <Link
          to={`/client/${clientSlug}`}
          className="inline-flex items-center gap-1.5 text-sm text-slate-500 hover:text-slate-900 transition-colors mb-6"
        >
          <ArrowLeft className="w-4 h-4" />
          Back to {client?.name}
        </Link>

        {/* Page header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold text-slate-900">Alerts</h1>
              {unacknowledgedCount > 0 && (
                <span className="bg-red-500 text-white text-xs font-bold rounded-full px-2 py-0.5">
                  {unacknowledgedCount} open
                </span>
              )}
            </div>
            <p className="text-slate-500 mt-1 text-sm">{client?.name} — security alerts feed</p>
          </div>

          <button
            onClick={loadData}
            className="inline-flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 rounded-lg text-sm text-slate-600 hover:bg-slate-50 hover:text-slate-900 transition-colors shadow-sm"
          >
            <RefreshCw className="w-3.5 h-3.5" />
            Refresh
          </button>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-4 mb-6 flex flex-col sm:flex-row flex-wrap items-start sm:items-center gap-3 sm:gap-4">
          <div className="flex flex-col sm:flex-row sm:items-center gap-2">
            <label className="text-xs font-semibold text-slate-600 uppercase tracking-wide">Severity</label>
            <div className="flex flex-wrap gap-1">
              {['ALL', 'HIGH', 'MEDIUM', 'LOW', 'INFO'].map((sev) => (
                <button
                  key={sev}
                  onClick={() => setFilterSeverity(sev)}
                  className={`px-3 py-1 rounded-full text-xs font-medium transition-colors ${
                    filterSeverity === sev
                      ? 'bg-slate-800 text-white'
                      : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                  }`}
                >
                  {sev}
                </button>
              ))}
            </div>
          </div>

          <label className="flex items-center gap-2 text-sm text-slate-600 cursor-pointer sm:ml-auto">
            <input
              type="checkbox"
              checked={showAcknowledged}
              onChange={(e) => setShowAcknowledged(e.target.checked)}
              className="w-4 h-4 rounded border-slate-300 text-teal-600 cursor-pointer"
            />
            Show acknowledged
          </label>
        </div>

        {/* Alerts list */}
        {filteredAlerts.length === 0 ? (
          <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-16 text-center">
            <CheckCircle2 className="w-12 h-12 text-emerald-400 mx-auto mb-4" />
            <p className="text-slate-800 font-medium">No alerts to show</p>
            <p className="text-slate-400 text-sm mt-1">
              {!showAcknowledged && alerts.length > 0
                ? 'All alerts have been acknowledged. Toggle "Show acknowledged" to view them.'
                : 'No alerts have been generated for this client yet.'}
            </p>
          </div>
        ) : (
          <div className="space-y-3">
            {filteredAlerts.map((alert) => {
              const sev = (alert.severity || 'INFO').toUpperCase()
              const style = getSeverityStyle(sev)
              const vendor = vendorMap[alert.vendor_id]
              const isAcked = !!alert.acknowledged
              const isAcking = acknowledging.has(alert.id)

              return (
                <div
                  key={alert.id}
                  className={`bg-white rounded-xl border shadow-sm transition-opacity ${
                    isAcked ? 'opacity-60' : ''
                  } ${style.border}`}
                >
                  <div className="p-5 flex items-start gap-4">
                    {/* Severity icon */}
                    <div className={`p-2 rounded-lg flex-shrink-0 ${style.bg}`}>
                      {SEVERITY_ICON[sev] || SEVERITY_ICON.INFO}
                    </div>

                    {/* Content */}
                    <div className="flex-1 min-w-0">
                      <div className="flex flex-wrap items-start justify-between gap-2">
                        <div>
                          <div className="flex flex-wrap items-center gap-2 mb-1">
                            <span
                              className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-bold ${style.badge}`}
                            >
                              {sev}
                            </span>
                            {alert.alert_type && (
                              <span className="text-xs text-slate-500 font-mono bg-slate-100 px-2 py-0.5 rounded">
                                {alert.alert_type}
                              </span>
                            )}
                          </div>
                          <p className="text-sm font-semibold text-slate-800">{alert.message}</p>
                          {vendor && (
                            <Link
                              to={`/client/${clientSlug}/vendor/${vendor.id}`}
                              className="text-xs text-mtm-teal hover:underline mt-1 inline-block"
                            >
                              {vendor.name} ({vendor.domain})
                            </Link>
                          )}
                        </div>

                        {/* Timestamp + ack button */}
                        <div className="flex-shrink-0 text-right">
                          <p className="text-xs text-slate-400">{formatDate(alert.sent_at)}</p>
                          {isAcked ? (
                            <span className="inline-flex items-center gap-1 text-xs text-emerald-600 mt-1.5 font-medium">
                              <CheckCircle2 className="w-3.5 h-3.5" />
                              Acknowledged
                            </span>
                          ) : (
                            <button
                              onClick={() => acknowledgeAlert(alert.id)}
                              disabled={isAcking}
                              className="mt-1.5 inline-flex items-center gap-1.5 px-3 py-1 bg-slate-100 hover:bg-emerald-100 hover:text-emerald-700 text-slate-600 text-xs font-medium rounded-lg transition-colors disabled:opacity-50"
                            >
                              {isAcking ? (
                                <>
                                  <div className="w-3 h-3 border-2 border-current border-t-transparent rounded-full animate-spin" />
                                  Saving...
                                </>
                              ) : (
                                <>
                                  <CheckCircle2 className="w-3.5 h-3.5" />
                                  Acknowledge
                                </>
                              )}
                            </button>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </main>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { Shield, Building2, ChevronRight, Calendar, ArrowRight } from 'lucide-react'
import { supabase } from '../lib/supabase'
import { formatScore, formatDate, getGradeStyle, scoreToGrade } from '../lib/gradeUtils'
import AppHeader from '../components/AppHeader'
import LoadingSpinner from '../components/LoadingSpinner'
import ErrorMessage from '../components/ErrorMessage'

export default function ClientSelector() {
  const [clients, setClients] = useState([])
  const [clientStats, setClientStats] = useState({})
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  async function loadClients() {
    setLoading(true)
    setError(null)

    try {
      const { data: clientData, error: clientError } = await supabase
        .from('sentinel_clients')
        .select('*')
        .eq('active', true)
        .order('name')

      if (clientError) throw clientError

      const stats = {}
      await Promise.all(
        (clientData || []).map(async (client) => {
          const { data: vendors } = await supabase
            .from('sentinel_vendors')
            .select('id, last_score, last_scanned_at')
            .eq('client_id', client.id)

          const totalVendors = vendors?.length || 0
          const scoredVendors = vendors?.filter((v) => v.last_score !== null) || []
          const avgScore =
            scoredVendors.length > 0
              ? scoredVendors.reduce((sum, v) => sum + v.last_score, 0) / scoredVendors.length
              : null

          const latestScan = vendors
            ?.filter((v) => v.last_scanned_at)
            .sort((a, b) => new Date(b.last_scanned_at) - new Date(a.last_scanned_at))[0]
            ?.last_scanned_at

          const { count: alertCount } = await supabase
            .from('sentinel_alerts')
            .select('id', { count: 'exact', head: true })
            .eq('client_id', client.id)
            .is('acknowledged', null)

          stats[client.id] = {
            totalVendors,
            avgScore,
            latestScan,
            unacknowledgedAlerts: alertCount || 0,
          }
        })
      )

      setClients(clientData || [])
      setClientStats(stats)
    } catch (err) {
      console.error('Failed to load clients:', err)
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadClients()
  }, [])

  return (
    <div className="min-h-screen bg-mtm-bg">
      <AppHeader />

      <main className="max-w-screen-xl mx-auto px-4 sm:px-6 py-8 sm:py-10">
        {/* Page header */}
        <div className="mb-10">
          <h1 className="text-3xl font-extrabold text-mtm-primary tracking-tight">
            Client Portfolio
          </h1>
          <p className="text-stone-500 mt-2 text-[15px]">
            Select a client to view their vendor security posture.
          </p>
        </div>

        {loading && <LoadingSpinner message="Loading clients..." />}
        {error && <ErrorMessage message={error} onRetry={loadClients} />}

        {!loading && !error && clients.length === 0 && (
          <div className="text-center py-24">
            <Shield className="w-12 h-12 text-stone-300 mx-auto mb-4" />
            <p className="text-stone-500">No active clients found.</p>
          </div>
        )}

        {!loading && !error && clients.length > 0 && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
            {clients.map((client) => {
              const stats = clientStats[client.id] || {}
              const avgScore = stats.avgScore
              const grade = avgScore !== null ? scoreToGrade(avgScore) : null
              const gradeStyle = grade ? getGradeStyle(grade) : null
              const hasData = stats.totalVendors > 0

              return (
                <Link
                  key={client.id}
                  to={`/client/${client.slug}`}
                  className={`sentinel-card group ${hasData ? '' : 'opacity-75'}`}
                >
                  <div className="p-6">
                    {/* Header row */}
                    <div className="flex items-start justify-between mb-5">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-lg flex items-center justify-center"
                          style={{
                            background: hasData
                              ? 'linear-gradient(135deg, #1e3a5f, #0f172a)'
                              : '#cbd5e1',
                          }}>
                          <Building2 className="w-5 h-5 text-white" strokeWidth={1.5} />
                        </div>
                        <div>
                          <h2 className="font-bold text-mtm-dark text-[15px] leading-tight group-hover:text-mtm-primary transition-colors">
                            {client.name}
                          </h2>
                          <p className="text-[11px] text-stone-400 mt-0.5 font-mono tracking-wide">
                            {client.slug}
                          </p>
                        </div>
                      </div>
                      {gradeStyle && (
                        <div
                          className="grade-badge w-11 h-11 text-xl"
                          style={{ backgroundColor: gradeStyle.bg, color: gradeStyle.text }}
                        >
                          {grade}
                        </div>
                      )}
                    </div>

                    {/* Stats */}
                    <div className="grid grid-cols-3 gap-2.5 mb-5">
                      <div className="stat-block">
                        <p className="text-xl font-bold text-mtm-dark">
                          {stats.totalVendors ?? 0}
                        </p>
                        <p className="text-[10px] font-medium text-stone-400 mt-0.5 uppercase tracking-wider">
                          Vendors
                        </p>
                      </div>
                      <div className="stat-block">
                        <p className="text-xl font-bold"
                          style={gradeStyle ? { color: gradeStyle.bg } : { color: '#94a3b8' }}>
                          {avgScore !== null ? formatScore(avgScore) : '--'}
                        </p>
                        <p className="text-[10px] font-medium text-stone-400 mt-0.5 uppercase tracking-wider">
                          Avg Score
                        </p>
                      </div>
                      <div className="stat-block">
                        <p className={`text-xl font-bold ${
                          stats.unacknowledgedAlerts > 0 ? 'text-red-600' : 'text-emerald-600'
                        }`}>
                          {stats.unacknowledgedAlerts || 0}
                        </p>
                        <p className="text-[10px] font-medium text-stone-400 mt-0.5 uppercase tracking-wider">
                          Alerts
                        </p>
                      </div>
                    </div>

                    {/* Footer */}
                    <div className="flex items-center justify-between pt-4 border-t border-stone-100">
                      <div className="flex items-center gap-1.5 text-[11px] text-stone-400">
                        <Calendar className="w-3 h-3" />
                        <span>{formatDate(stats.latestScan) === 'Never' ? 'No scans yet' : `Last scan: ${formatDate(stats.latestScan)}`}</span>
                      </div>
                      <span className="view-button">
                        View <ArrowRight className="w-3 h-3" />
                      </span>
                    </div>
                  </div>
                </Link>
              )
            })}
          </div>
        )}

        {/* Footer attribution */}
        <div className="mt-16 pt-8 border-t border-stone-200/60 text-center">
          <p className="text-[11px] text-stone-400 font-medium">
            MTM Sentinel v2.0 &middot; External Security Monitor &middot; <span className="text-mtm-teal">Meet the Moment</span>
          </p>
        </div>
      </main>
    </div>
  )
}

