import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

// https://vite.dev/config/
export default defineConfig({
  plugins: [react()],
  server: {
    port: 5174,
  },
  build: {
    chunkSizeWarningLimit: 1000,
  },
})

import { Link, useLocation } from 'react-router-dom'
import { Bell } from 'lucide-react'

/**
 * Top navigation header for MTM Sentinel.
 * Shows logo, current context breadcrumb, and alerts link.
 */
export default function AppHeader({ clientName, clientSlug, vendorName, alertCount = 0 }) {
  const location = useLocation()

  return (
    <header className="sticky top-0 z-50" style={{
      background: 'linear-gradient(135deg, #0a1628 0%, #1e3a5f 60%, #1a3354 100%)',
      boxShadow: '0 2px 16px rgba(10, 22, 40, 0.3)',
    }}>
      <div className="max-w-screen-xl mx-auto px-4 sm:px-6">
        <div className="flex items-center justify-between h-16">
          {/* Logo + Brand */}
          <Link to="/" className="flex items-center gap-3 group">
            <div className="w-9 h-9 rounded-lg flex items-center justify-center" style={{
              background: 'linear-gradient(135deg, #0d9488, #0f766e)',
              boxShadow: '0 2px 8px rgba(13, 148, 136, 0.3)',
            }}>
              <svg width="18" height="18" viewBox="0 0 32 32" fill="none">
                <path d="M16 2L4 8v8c0 8 5 15 12 18 7-3 12-10 12-18V8L16 2z" fill="white" fillOpacity="0.95"/>
                <path d="M13.5 20l-4-4 2-2 2 2 5-5 2 2-7 7z" fill="#0f766e"/>
              </svg>
            </div>
            <div className="leading-none">
              <div className="flex items-baseline gap-2">
                <span className="text-white font-bold text-lg tracking-tight">MTM Sentinel</span>
                <span className="hidden sm:inline text-[10px] font-semibold tracking-[0.15em] uppercase"
                  style={{ color: 'rgba(13, 148, 136, 0.8)' }}>
                  Security Monitor
                </span>
                <span className="hidden sm:inline text-[9px] font-mono px-1.5 py-0.5 rounded"
                  style={{ backgroundColor: 'rgba(13, 148, 136, 0.15)', color: 'rgba(13, 148, 136, 0.9)' }}>
                  v2.0
                </span>
              </div>
              <span className="text-[11px] font-medium" style={{ color: 'rgba(148, 163, 184, 0.7)' }}>
                Meet the Moment
              </span>
            </div>
          </Link>

          {/* Breadcrumb */}
          <nav className="hidden sm:flex items-center gap-2 text-sm">
            <Link to="/" className="text-slate-400 hover:text-white transition-colors font-medium">
              Clients
            </Link>
            {clientName && (
              <>
                <span className="text-slate-600">/</span>
                <Link
                  to={`/client/${clientSlug}`}
                  className={`transition-colors font-medium ${vendorName ? 'text-slate-400 hover:text-white' : 'text-white'}`}
                >
                  {clientName}
                </Link>
              </>
            )}
            {vendorName && (
              <>
                <span className="text-slate-600">/</span>
                <span className="text-white font-medium">{vendorName}</span>
              </>
            )}
          </nav>

          {/* Alerts indicator */}
          <div className="flex items-center gap-4">
            {clientSlug && (
              <Link
                to={`/client/${clientSlug}/alerts`}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-semibold transition-all ${
                  location.pathname.endsWith('/alerts')
                    ? 'text-white'
                    : 'text-slate-300 hover:text-white hover:bg-white/10'
                }`}
                style={location.pathname.endsWith('/alerts') ? {
                  background: 'rgba(13, 148, 136, 0.25)',
                  border: '1px solid rgba(13, 148, 136, 0.3)',
                } : { border: '1px solid transparent' }}
              >
                <Bell className="w-4 h-4" />
                <span>Alerts</span>
                {alertCount > 0 && (
                  <span className="ml-1 bg-red-500 text-white text-[10px] font-bold rounded-full w-5 h-5 flex items-center justify-center">
                    {alertCount > 99 ? '99+' : alertCount}
                  </span>
                )}
              </Link>
            )}
          </div>
        </div>
      </div>

      {/* Subtle bottom accent line */}
      <div className="h-[2px]" style={{
        background: 'linear-gradient(90deg, transparent, #0d9488 30%, #0d9488 70%, transparent)',
        opacity: 0.4,
      }} />
    </header>
  )
}

